import { useRulesText } from "./use-rules-text"

/**
 * Rules-text resolution for unit abilities (NPCs and characters share ability ids), from the
 * per-ability `npcAbilityText/<id>` game-data namespaces (ported from V1's ability table; one small
 * file per id, generated by `scripts/generate-ability-text-i18n.mjs`). The served datasets carry
 * ability ids only; the `{[variable]}` tokens in a description are resolved against these
 * per-ability-level tables, indexed by the selected stat row's `abilityLevel`.
 *
 * Only abilities whose description resolves **completely** from its own variable and constant
 * tables have a file, so a caller can never render a leftover token. The referenced ids without one
 * are listed in `npcAbilityTextGaps` and never requested; they read as missing text, and the caller
 * renders the name alone.
 */
export type AbilityTextEntry = {
  description: string
  variables: Record<string, (string | number)[]>
  /** Level-independent values (hit counts, ranges, damage profiles) the description also references. */
  constants: Record<string, string>
  /** Variable names multiplied by the rarity factor when rendered. */
  scaled: string[]
}

export type TraitTextEntry = {
  description: string
  variables: Record<string, (string | number)[]>
}

/** The rules text of the given abilities, fetched per ability after the page paints. */
export function useAbilityText(abilityIds: readonly string[]) {
  return useRulesText<AbilityTextEntry>({
    namespace: "npcAbilityText",
    gaps: "npcAbilityTextGaps",
    ids: abilityIds,
  })
}

/**
 * The same resolution for trait rules text, from the whole `npcTraitText` namespace (small, so not
 * split). V1 ships trait descriptions in English only, so this namespace is en-only and other
 * languages fall back to it, mirroring `raidBossTraitText`; the localized trait *name* comes from the
 * `traits` namespace. Traits have no levels — each value is stored as a single-element array so the
 * shared renderer, which indexes variables by level, resolves them at level 1.
 */
export function useTraitText() {
  return useRulesText<TraitTextEntry>({ namespace: "npcTraitText" })
}
